import manifest from "@/generated/manifest.json";
import { bump } from "./stats";
import type { Template } from "./templates";

/* Client-safe helpers. File contents live server-side (see lib/zip.ts); the numbers below are generated by scripts/generate.mjs. */

export type Metrics = { lines: number; chars: number; tokens: number; kb: number };

const M = manifest.metrics as Record<string, Metrics>;

/** Size of what the author wrote (template files + shared engine). Tokens ≈ chars / 4. */
export function metricsFor(slug: string): Metrics {
  return M[slug] ?? { lines: 0, chars: 0, tokens: 0, kb: 0 };
}

export const ZIP_FILE_TREE = [
  "index.html",
  "style.css",
  "main.js",
  "shared/core.js",
  "shared/base.css",
  "vendor/three.module.min.js",
  "vendor/addons/…",
  "README.md",
  "PROMPTS.md",
  "AI_CONTEXT.md",
  "LICENSE.txt",
  "package.json",
];

/** Trigger a download from a URL. */
export function downloadUrl(url: string, name: string) {
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
}

/** The server builds the zip and the browser saves it. */
export async function downloadTemplate(t: Template): Promise<void> {
  bump(t.slug, "download");
  downloadUrl(`/api/download/template/${t.slug}`, `${t.slug}-3d-template.zip`);
}
